const WIDTH=32,HEIGHT=112,CELLS=WIDTH*HEIGHT;
// Remember only tiles touched by player sight, never tiles generated by the renderer.
export class Exploration {
 constructor(saved=[]){this.chunks=new Map();this.visible=new Set();this.count=0;for(const [cx,runs]of saved){const data=new Uint8Array(CELLS);let at=0;for(let i=0;i<runs.length;i+=2){data.fill(runs[i+1],at,at+runs[i]);at+=runs[i];}this.chunks.set(cx,data);for(const t of data)if(t)this.count++;}}
 address(x,y){x=Math.floor(x);y=Math.floor(y);return [Math.floor(x/WIDTH),y*WIDTH+((x%WIDTH)+WIDTH)%WIDTH];}
 get(x,y){if(y<0||y>=HEIGHT)return null;const [cx,i]=this.address(x,y),n=this.chunks.get(cx)?.[i]||0;return n?n-1:null;}
 remember(x,y,t){if(y<0||y>=HEIGHT)return;const [cx,i]=this.address(x,y);if(!this.chunks.has(cx))this.chunks.set(cx,new Uint8Array(CELLS));const row=this.chunks.get(cx);if(!row[i])this.count++;row[i]=t+1;}
 reveal(world,x,y,radius){this.visible.clear();for(let angle=0;angle<360;angle+=2){const dx=Math.cos(angle*Math.PI/180),dy=Math.sin(angle*Math.PI/180);for(let r=0;r<=radius;r+=.45){const a=Math.floor(x+dx*r),b=Math.floor(y+dy*r);if(b<0||b>=HEIGHT)continue;const t=world.get(a,b);this.remember(a,b,t);this.visible.add(`${a},${b}`);if(world.solid(a,b))break;}}}
 serialize(){return [...this.chunks].map(([cx,data])=>{const runs=[];let value=data[0],n=0;for(const t of data){if(t===value)n++;else{runs.push(n,value);value=t;n=1;}}runs.push(n,value);return [cx,runs];});}
 static valid(saved,maxTile=50){return Array.isArray(saved)&&saved.length<=20000&&new Set(saved.map(e=>e?.[0])).size===saved.length&&saved.every(e=>Array.isArray(e)&&e.length===2&&Number.isSafeInteger(e[0])&&Array.isArray(e[1])&&e[1].length>0&&e[1].length%2===0&&e[1].length<=CELLS*2&&e[1].every((n,i)=>Number.isInteger(n)&&n>=(i%2?0:1)&&n<=(i%2?maxTile+1:CELLS))&&e[1].filter((_,i)=>i%2===0).reduce((n,v)=>n+v,0)===CELLS);}
}
